def pin(p):
 raw=p.read_bytes();return {"path":str(p),"sha256":"sha256:"+hashlib.sha256(raw).hexdigest(),"bytes":len(raw)}
def emit(name,value):
 with (N/name).open("xb") as f:f.write((json.dumps(value,ensure_ascii=True,indent=2)+"\n").encode())
