header="\"\"\"Inert Root C12 request writer: never runs the archive helper.\"\"\"\nimport sys\nsys.dont_write_bytecode = True\nimport hashlib\nimport json\nimport ntpath\nimport os\nfrom pathlib import Path\nimport re\nimport types\n\nCONFIG = __CONFIG__\nHELPER = __HELPER__\nREQUEST_DIRECTORY = __Q12__\nREQUEST_PATH = str(Path(REQUEST_DIRECTORY) / \"grant-public-pin-archive.request.json\")\nARCHIVE_DIRECTORY = __ARCHIVE__\nFULL_FLAG = \"--select-full-current-grant-public-pins\"\nCAP = 128 * 1024 * 1024\n\ndef require(value, message):\n    if not value:\n        raise ValueError(message)\n\ndef canonical(value):\n    require(type(value) is str and value, \"absolute public path\")\n    p = value.replace(\"/\", \"\\\\\")\n    drive, tail = ntpath.splitdrive(p)\n    require(re.fullmatch(\"[A-Za-z]:\", drive) and tail.startswith(\"\\\\\") and\n            not tail.startswith(\"\\\\\\\\\") and \":\" not in tail and all(ord(c) >= 32 for c in p),\n            \"local public path only\")\n    require(all(x and x not in (\".\", \"..\") and not x.endswith((\" \", \".\")) and\n        not re.match(r\"(?i)^(CON|PRN|AUX|NUL|CONIN\\$|CONOUT\\$|COM[1-9\u00b9\u00b2\u00b3]|LPT[1-9\u00b9\u00b2\u00b3])(?:\\.|$)\",x)\n        for x in tail[1:].split(\"\\\\\")), \"regular path components\")\n    require(ntpath.normcase(str(Path(value).resolve())) == ntpath.normcase(p), \"canonical path required\")\n    return ntpath.normcase(p)\n\ndef validate_ref(value):\n    require(type(value) is dict and set(value) == {\"path\",\"sha256\",\"bytes\"}, \"exact public ref\")\n    canonical(value[\"path\"])\n    require(type(value[\"sha256\"]) is str and re.fullmatch(\"sha256:[0-9a-f]{64}\",value[\"sha256\"]),\n            \"prefixed lowercase digest\")\n    require(type(value[\"bytes\"]) is int and 0 <= value[\"bytes\"] <= CAP, \"bounded integer bytes\")\n    return value\n\ndef bounded_read(value):\n    validate_ref(value)\n    with Path(value[\"path\"]).open(\"rb\") as stream:\n        raw = stream.read(value[\"bytes\"] + 1)\n    require(len(raw) == value[\"bytes\"], \"public input byte count\")\n    require(\"sha256:\" + hashlib.sha256(raw).hexdigest() == value[\"sha256\"], \"public input digest\")\n    return raw\n\ndef load_helper():\n    raw = bounded_read(HELPER)\n    module = types.ModuleType(\"gpa_bounded_source\")\n    module.__file__ = HELPER[\"path\"]\n    exec(compile(raw, HELPER[\"path\"], \"exec\"), module.__dict__)\n    return module\n\ndef select_full(m, payload, cfg, hc, manifest, explicit_flag):\n    require(explicit_flag == FULL_FLAG, \"Root explicit full selection required\")\n    pins, allowed = m.validate_grant(payload,cfg,hc)\n    names = [f[\"name\"] + \".enc\" for f in manifest[\"files\"]]\n    require(names and len(names) == len(set(names)) and\n            all(re.fullmatch(\"[A-Za-z0-9_][A-Za-z0-9_.-]*\\\\.enc\",n) for n in names),\n            \"cipher manifest filename closure\")\n    require({\"encrypted-backup-payload:\" + n for n in names} ==\n            {r for r in allowed if r.startswith(\"encrypted-backup-payload:\")}, \"cipher manifest role closure\")\n    entries = [dict(allowed[r]) for r in sorted(allowed)]\n    chosen, missing = m.validate_selection(entries,allowed)\n    require(not missing and len([r for r in chosen if r.startswith(\"source-inventory:\")]) == 28 and\n            len([r for r in chosen if r.startswith(\"target-inventory:\")]) == 29 and\n            \"migration-sql\" not in chosen, \"full fixed unique selection\")\n    return entries\n\ndef compose(snapshot_ref, explicit_flag):\n    require(explicit_flag == FULL_FLAG, \"Root explicit full selection required\")\n    validate_ref(snapshot_ref)\n    expected_parent = str(Path(CONFIG[\"path\"]).parent / \"controller-runtime\")\n    require(canonical(str(Path(snapshot_ref[\"path\"]).parent)) == canonical(expected_parent) and\n            re.fullmatch(\"review-snapshot-grant-[0-9a-f]{32}\\\\.json\",Path(snapshot_ref[\"path\"]).name),\n            \"existing fixed grant snapshot only\")\n    m = load_helper()\n    ref,decode,same,plain,counter = m.ref,m.decode,m.same,m.plain,m.counter\n    validate_grant,validate_selection = m.validate_grant,m.validate_selection\n    CONFIG_SHA,CONFIG_BYTES = m.CONFIG_SHA,m.CONFIG_BYTES\n    HARNESS_SHA,HARNESS_BYTES,CASE_ID = m.HARNESS_SHA,m.HARNESS_BYTES,m.CASE_ID\n    frozen = {}\n    def read_ref(value):\n        raw = bounded_read(value)\n        key = canonical(value[\"path\"])\n        require(key not in frozen or same(frozen[key],value), \"conflicting metadata input\")\n        frozen[key] = dict(value)\n        return raw\n    snapshot = decode(read_ref(snapshot_ref))\n    require(snapshot.get(\"case_id\") == CASE_ID and snapshot.get(\"phase\") == \"grant\", \"fixed case/grant snapshot\")\n    request = {\"Schema\":\"researchos.native-grant-public-pin-archive-request.v1\",\n        \"HelperSource\":dict(HELPER),\"Config\":dict(CONFIG),\"Snapshot\":dict(snapshot_ref),\n        \"Payload\":snapshot[\"payload_ref\"],\"OutputDirectory\":ARCHIVE_DIRECTORY,\"Entries\":[]}\n"
footer="    manifest = decode(read_ref(plain(allowed[\"encrypted-backup-manifest\"])))\n    request[\"Entries\"] = select_full(m,payload,cfg,hc,manifest,explicit_flag)\n    chosen,missing = validate_selection(request[\"Entries\"],allowed)\n    require(not missing, \"full selection only\")\n    m.lifecycle(cfg,hc)\n    m.output_boundary(ARCHIVE_DIRECTORY,cfg,hc,list(frozen.values()) + [HELPER])\n    require(Path(REQUEST_DIRECTORY).is_dir() and canonical(str(Path(REQUEST_PATH).parent)) == canonical(REQUEST_DIRECTORY),\n            \"existing fixed Root request directory required\")\n    require(not os.path.lexists(REQUEST_PATH), \"fresh fixed request destination\")\n    require(not any(m.inside(REQUEST_PATH,p) for p in\n        (cfg[\"ControllerDirectory\"],hc[\"OutputDirectory\"],hc[\"BuildRoot\"],cfg[\"Environment\"][\"TEMP\"])),\n        \"request outside controlled resources\")\n    for value in frozen.values():\n        bounded_read(value)\n    bounded_read(HELPER)\n    m.lifecycle(cfg,hc)\n    m.output_boundary(ARCHIVE_DIRECTORY,cfg,hc,list(frozen.values()) + [HELPER])\n    return request\n\ndef write_request(request):\n    canonical(REQUEST_DIRECTORY)\n    canonical(REQUEST_PATH)\n    require(Path(REQUEST_DIRECTORY).is_dir() and not os.path.lexists(REQUEST_PATH), \"fresh fixed request\")\n    raw = (json.dumps(request,ensure_ascii=True,indent=2) + \"\\n\").encode(\"utf-8\")\n    with Path(REQUEST_PATH).open(\"xb\") as stream:\n        require(stream.write(raw) == len(raw), \"short request write\")\n        stream.flush()\n        os.fsync(stream.fileno())\n    result = {\"path\":REQUEST_PATH,\"sha256\":\"sha256:\" + hashlib.sha256(raw).hexdigest(),\"bytes\":len(raw)}\n    require(bounded_read(result) == raw, \"request readback differs\")\n    return result\n\ndef main():\n    require(len(sys.argv) == 5, \"SNAPSHOT_PATH SNAPSHOT_SHA256 SNAPSHOT_BYTES --select-full-current-grant-public-pins\")\n    require(re.fullmatch(\"0|[1-9][0-9]*\",sys.argv[3]), \"decimal snapshot byte count\")\n    request = compose({\"path\":sys.argv[1],\"sha256\":sys.argv[2],\"bytes\":int(sys.argv[3])},sys.argv[4])\n    result = write_request(request)\n    print(\"ROOT_ARCHIVE_REQUEST_WRITTEN \" + json.dumps(result,ensure_ascii=True))\n\nif __name__ == \"__main__\":\n    main()\n"
header=header.replace("__CONFIG__",repr(config)).replace("__HELPER__",repr(helper)).replace("__Q12__",repr(str(Q))).replace("__ARCHIVE__",repr(str(A)))
